using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

public static class NemoWalkRegionVerifier
{
    [Serializable]class Result{public int seed,allowedCells,reachableCells,contours,forestHoles,routeSamples,routeOutside,parcelVisiblePixels,walkVisiblePixels,unreachableHubs,unreachableEntries;public bool designFirst,noVisualChanges,noBoundaryDecorations,success,parcelToggle,walkToggle,offRestored,collidersUnchanged,defaultOff;public string[] errors;}
    [Serializable]class Report{public bool success;public Result[] seeds;public string scope;}
    static int PixelDifference(string before,string after){var a=new Texture2D(2,2);var b=new Texture2D(2,2);a.LoadImage(File.ReadAllBytes(before));b.LoadImage(File.ReadAllBytes(after));var ap=a.GetPixels32();var bp=b.GetPixels32();int count=ap.Where((p,i)=>Mathf.Abs(p.r-bp[i].r)+Mathf.Abs(p.g-bp[i].g)+Mathf.Abs(p.b-bp[i].b)>30).Count();UnityEngine.Object.DestroyImmediate(a);UnityEngine.Object.DestroyImmediate(b);return count;}
    public static void Inspect(){var results=new List<Result>();foreach(int seed in new[]{0,17,42,99,20261011}){var r=new Result{seed=seed};var issues=new List<string>();try{EditorSceneManager.OpenScene(seed==0?NemoRiverVerifier.ScenePath:"Assets/NemoBlocks/Scenes/RiverSeeds/NemoRiverSeed"+seed+".unity");var w=UnityEngine.Object.FindAnyObjectByType<NemoWalk>();var m=w.Map;var region=m.Boundary.WalkRegion;r.designFirst=m.Design!=null;r.noVisualChanges=m.Design.NoVisualMutation&&m.Design.VisualDigest==NemoBlockDesignFreeze.Digest(m);r.noBoundaryDecorations=m.Boundary.NativeBarrierCount==0&&m.Boundary.AddedTreeFeet.Length==0&&m.Boundary.GetComponentsInChildren<SpriteRenderer>().Length==0;r.allowedCells=region.AllowedCells;r.contours=region.Contours.Length;r.forestHoles=region.ForestIslands.Length;
        const int width=NemoWalkRegion.Width,height=NemoWalkRegion.Height;var visited=new bool[width*height];var queue=new Queue<int>();int Index(Vector2 p)=>Mathf.FloorToInt(p.x/NemoWalkRegion.Step)+Mathf.FloorToInt(p.y/NemoWalkRegion.Step)*width;Vector2 Point(int k)=>new Vector2((k%width+.5f)*NemoWalkRegion.Step,(k/width+.5f)*NemoWalkRegion.Step);int start=Index(m.Plan.parcels[0].hub);visited[start]=true;queue.Enqueue(start);while(queue.Count>0){int k=queue.Dequeue();r.reachableCells++;int x=k%width,y=k/width;foreach(int n in new[]{x>0?k-1:-1,x<width-1?k+1:-1,y>0?k-width:-1,y<height-1?k+width:-1})if(n>=0&&!visited[n]&&region.Contains(Point(n))){visited[n]=true;queue.Enqueue(n);}}
        foreach(var parcel in m.Plan.parcels.Where(p=>!p.land||m.Plan.links.Any(e=>e.a==p.id||e.b==p.id)))if(!visited[Index(parcel.hub)])r.unreachableHubs++;foreach(var route in m.Plan.links.Select(e=>e.points).Concat(m.Approaches.Select(a=>a.points))){foreach(var point in route){r.routeSamples++;if(!region.Contains(point))r.routeOutside++;}if(!visited[Index(route.Last())])r.unreachableEntries++;}
        var bodies=m.World.GetComponentsInChildren<Collider2D>();int active=bodies.Count(c=>c.enabled);r.defaultOff=!m.Overlay.activeSelf&&!region.Overlay.activeSelf;string file=Path.Combine(NemoBuilder.Evidence,"walk-seed-"+seed);NemoBuilder.Capture(w.View,w.BodyCenter,NemoWalk.NormalCameraSize,file+"-debug-off-before.png");NemoBuilder.Capture(w.View,new Vector2(72,54),56,file+"-overview-off.png",1728,1296);w.ToggleParcels();r.parcelToggle=m.Overlay.activeSelf&&!region.Overlay.activeSelf&&m.Overlay.GetComponentsInChildren<LineRenderer>().Length==m.Plan.parcels.Length;NemoBuilder.Capture(w.View,new Vector2(72,54),56,file+"-parcels.png",1728,1296);w.ToggleParcels();w.ToggleWalkArea();r.walkToggle=region.Overlay.activeSelf&&!m.Overlay.activeSelf&&region.Overlay.GetComponentsInChildren<LineRenderer>().Length==region.Contours.Length;NemoBuilder.Capture(w.View,new Vector2(72,54),56,file+"-walk-contours.png",1728,1296);w.ToggleWalkArea();NemoBuilder.Capture(w.View,w.BodyCenter,NemoWalk.NormalCameraSize,file+"-debug-off-after.png");r.parcelVisiblePixels=PixelDifference(file+"-overview-off.png",file+"-parcels.png");r.walkVisiblePixels=PixelDifference(file+"-overview-off.png",file+"-walk-contours.png");r.offRestored=File.ReadAllBytes(file+"-debug-off-before.png").SequenceEqual(File.ReadAllBytes(file+"-debug-off-after.png"));r.collidersUnchanged=active==bodies.Count(c=>c.enabled);
        if(!r.designFirst||!r.noVisualChanges||!r.noBoundaryDecorations)issues.Add("Boundary was not derived from unchanged completed block design");if(r.unreachableHubs+r.unreachableEntries+r.routeOutside>0||r.allowedCells!=r.reachableCells)issues.Add("Region access/continuity mismatch");if(r.parcelVisiblePixels<1000||r.walkVisiblePixels<1000)issues.Add("Overlay not visibly rendered in actual GPU overview");if(!r.defaultOff||!r.parcelToggle||!r.walkToggle||!r.offRestored||!r.collidersUnchanged)issues.Add("Debug toggle did not preserve normal display/physics");
    }catch(Exception e){issues.Add(e.ToString());Debug.LogException(e);}r.errors=issues.ToArray();r.success=issues.Count==0;results.Add(r);File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"walk-seed-"+seed+"-region.json"),JsonUtility.ToJson(r,true));Debug.Log("NEMO_WALK_REGION "+seed+" "+r.success);}File.WriteAllText(Path.Combine(NemoBuilder.Evidence,"walk-region-verification.json"),JsonUtility.ToJson(new Report{success=results.Count==5&&results.All(r=>r.success),seeds=results.ToArray(),scope="Saved scenes: 1/16-unit ground region derived from immutable native forest pixels and rendered soil/yard triangles flood-fill from central hub, all hubs/route samples/site entries. G block allocation and H organic walking contour toggles separately; exact off-before/off-after GPU PNG identity, unchanged Collider enabled count. Same methods invoked by normal keys and GUI buttons; manual keyboard injection excluded. Terrain/body obstacles separately tested by actual Physics2D."},true));EditorSceneManager.OpenScene(NemoRiverVerifier.ScenePath);}
}
